class Circle:
    def __init__(self, radius): self.radius = radius
    @property
    def diameter(self): return self.radius * 2
print(Circle(3).diameter)

class Temperature:
    def __init__(self, c): self.celsius = c
    @property
    def celsius(self): return self._celsius
    @celsius.setter
    def celsius(self, value):
        if value < -273.15: raise ValueError('below absolute zero')
        self._celsius = value
print(Temperature(20).celsius)
